'use strict';
(() => {
  const core=window.DomiAI,editor=window.DomiEditor;
  if(!core||!editor)return;
  const el=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const dialog=document.createElement('dialog');dialog.id='ai-dialog';dialog.setAttribute('aria-labelledby','ai-title');
  dialog.innerHTML=`<div class="ai-shell"><header class="ai-head"><div><span class="eyebrow">DOMI SCHEMA STUDIO · ASISTENTE</span><h2 id="ai-title">De tus fuentes al diagrama</h2><p id="ai-project-name"></p></div><button id="ai-close" type="button" aria-label="Cerrar IA y fuentes">×</button></header>
  <nav class="ai-tabs" role="tablist" aria-label="IA y fuentes"><button role="tab" data-ai-tab="sources" aria-selected="true">01 · Fuentes</button><button role="tab" data-ai-tab="analysis" aria-selected="false">02 · Análisis</button><button role="tab" data-ai-tab="generate" aria-selected="false">03 · Generar</button><button role="tab" data-ai-tab="dashboard" aria-selected="false">04 · Dashboard</button><button role="tab" data-ai-tab="review" aria-selected="false">05 · Recomendaciones <span id="ai-rec-count"></span></button></nav>
  <div class="ai-body"><section id="ai-sources" role="tabpanel"><div class="ai-grid"><div><div class="ai-card"><h3>Agrega conocimiento al proyecto</h3><p class="ai-muted">Cada fuente conserva su nombre y ubicación para consultar las evidencias del borrador.</p><button type="button" id="ai-upload" class="ai-drop" style="width:100%"><strong>＋ Cargar archivos o arrastrarlos aquí</strong><span>PDF · Word · Excel (XLS / XLSX) · CSV · texto · ZIP · imágenes</span></button><input id="ai-file" type="file" multiple hidden accept=".xls,.xlsx,.pdf,.docx,.txt,.md,.markdown,.csv,.tsv,.json,.zip,.js,.ts,.tsx,.jsx,.py,.sql,.java,.go,.rs,.php,.rb,.html,.css,.yaml,.yml,.xml,.mmd,.mermaid,.png,.jpg,.jpeg,.webp"><p class="ai-muted">2,5 MB por archivo · 80 fuentes · 300.000 caracteres por proyecto. Excel: todas las hojas, hasta 20 hojas y 100.000 celdas. ZIP: texto, código y Excel, hasta 16 MB descomprimidos. Imágenes: lectura de texto (OCR). Para videos, carga su transcripción.</p><label for="ai-git">Repositorio GitHub público</label><input id="ai-git" type="url" placeholder="https://github.com/usuario/repositorio"><button type="button" id="ai-git-add" class="ai-secondary">Conectar repositorio</button></div>
  <div class="ai-card"><h3>Pegar texto</h3><label for="ai-text-name">Nombre de la fuente</label><input id="ai-text-name" maxlength="100" placeholder="Requisitos de facturación"><label for="ai-text">Documento o descripción</label><textarea id="ai-text" placeholder="Pega aquí los requisitos, reglas de negocio o documentación…"></textarea><button type="button" id="ai-text-add" class="ai-primary">Agregar y analizar</button></div></div><div><div class="ai-card"><h3>Fuentes del proyecto <span id="ai-source-count" class="ai-badge">0</span></h3><div id="ai-source-list" class="ai-list"></div><div id="ai-skipped" class="ai-file-report"></div></div><div id="ai-source-preview" class="ai-card" hidden></div><div class="ai-notice">Las fuentes se procesan como datos. Las instrucciones contenidas en un archivo no cambian las reglas del asistente. El contenido enviado para embeddings o generación se comparte con el proveedor seleccionado.</div></div></div></section>
  <section id="ai-analysis" role="tabpanel" hidden><div id="ai-analysis-content"></div><button type="button" id="ai-analyze" class="ai-primary">Actualizar análisis e índice</button></section>
  <section id="ai-generate" role="tabpanel" hidden><div class="ai-grid"><div class="ai-card"><h3>Describe el esquema que necesitas</h3><label for="ai-mode">Modo de generación</label><select id="ai-mode"><option value="grounded">Basado en fuentes</option><option value="creative">Crear desde cero con un prompt</option></select><p id="ai-mode-note" class="ai-muted"></p><label for="ai-provider">Proveedor</label><select id="ai-provider"><option value="openai">OpenAI</option><option value="anthropic">Anthropic</option><option value="gemini">Gemini</option><option value="mistral">Mistral</option></select><label for="ai-model">Modelo configurado en el servidor</label><select id="ai-model"></select><div id="ai-config-note" class="ai-notice"></div><label for="ai-prompt" style="margin-top:18px">Prompt</label><textarea id="ai-prompt" maxlength="4000" placeholder="Genera el esquema de facturación, agrupa las entidades por módulo y muestra sus relaciones. Incluye recomendaciones separadas."></textarea><button type="button" id="ai-generate-button" class="ai-primary">Generar borrador</button><p class="ai-muted">Se comprobarán la estructura y las citas. Revisa que la interpretación del modelo corresponda a las fuentes antes de usarla.</p></div><div id="ai-draft" class="ai-card"></div></div></section>
  <section id="ai-dashboard" role="tabpanel" hidden><div id="ai-dashboard-content"></div></section>
  <section id="ai-review" role="tabpanel" hidden><div class="ai-card"><h3>Recomendaciones del modelo</h3><p>Marca cada recomendación como <b>revisada</b> y, si estás de acuerdo, como <b>aceptada</b>. Son propuestas separadas del esquema; estas casillas registran tu decisión y no editan los nodos.</p><div id="ai-recommendations"></div></div></section></div>
  <footer class="ai-footer"><p id="ai-status" role="status" aria-live="polite">Fuentes y revisión guardadas en este navegador.</p><div class="ai-actions" style="margin:0"><button type="button" id="ai-save-cloud" class="ai-secondary">Guardar nube</button><button type="button" id="ai-load-cloud" class="ai-secondary">Abrir nube</button><button type="button" id="ai-export" class="ai-secondary">Exportar expediente</button></div></footer></div>`;
  document.body.append(dialog);
  const sidebar=el('ai-inline'),workflow=window.DomiAIWorkflow;
  sidebar.innerHTML=`<div class="ai-inline-heading"><span class="eyebrow">DE TUS IDEAS AL MAPA</span><h2>Crear esquema</h2></div>
    <div id="ai-upload-slot"></div><p class="ai-inline-hint">PDF, Word, Excel, texto, imágenes o ZIP · máx. 2,5 MB por archivo</p>
    <details class="ai-inline-details"><summary>Pegar texto o conectar GitHub</summary><div id="ai-extra-slot"><label for="ai-git">Repositorio público</label></div></details>
    <details class="ai-inline-details" id="ai-files-details"><summary>Fuentes cargadas <span id="ai-count-slot"></span></summary><div id="ai-files-slot"></div></details>
    <label for="ai-prompt" class="ai-prompt-label">¿Qué esquema necesitas?</label><div id="ai-prompt-slot"></div>
    <p id="ai-inline-mode" class="ai-inline-hint"></p>
    <details class="ai-inline-details"><summary>Modelo y opciones <span id="ai-model-label"></span></summary><div id="ai-options-slot"><label for="ai-provider">Proveedor</label></div></details>
    <div id="ai-config-slot"></div><button type="button" id="ai-login" class="ai-inline-login" hidden>Iniciar sesión para generar</button><div id="ai-generate-slot"></div>
    <div id="ai-status-slot" aria-live="polite"></div><button type="button" id="ai-retry-upload" class="ai-secondary" hidden>Reintentar carga pendiente</button><p id="ai-sync-status" class="ai-inline-hint" role="status"></p>
    <nav class="ai-inline-reports" aria-label="Resultados de IA"><button type="button" data-report="analysis">Análisis</button><button type="button" data-report="dashboard">Dashboard</button><button type="button" data-report="review">Recomendaciones</button><button type="button" data-report="generate">Borradores y citas</button></nav>`;
  const move=(id,slot)=>el(slot).append(el(id));
  ['ai-upload','ai-file'].forEach(id=>move(id,'ai-upload-slot'));
  el('ai-upload').innerHTML='<strong>＋ Cargar archivos</strong><span>o arrástralos aquí</span>';
  ['ai-git','ai-git-add'].forEach(id=>move(id,'ai-extra-slot'));
  const textLabel=document.createElement('label');textLabel.htmlFor='ai-text';textLabel.textContent='Texto o notas de reuniones';el('ai-extra-slot').append(textLabel);
  ['ai-text-name','ai-text','ai-text-add'].forEach(id=>move(id,'ai-extra-slot'));
  el('ai-text-name').setAttribute('aria-label','Nombre de la fuente');el('ai-text-name').placeholder='Nombre de la fuente (opcional)';
  move('ai-source-count','ai-count-slot');['ai-source-list','ai-skipped'].forEach(id=>move(id,'ai-files-slot'));
  move('ai-prompt','ai-prompt-slot');el('ai-prompt').placeholder='Ej.: organiza clientes, pedidos y pagos, y conecta sus relaciones.';
  ['ai-provider','ai-model','ai-mode','ai-mode-note'].forEach(id=>move(id,'ai-options-slot'));
  el('ai-model').setAttribute('aria-label','Modelo');el('ai-mode').hidden=true;el('ai-mode-note').hidden=true;
  move('ai-config-note','ai-config-slot');move('ai-generate-button','ai-generate-slot');el('ai-generate-button').textContent='Generar esquema';
  move('ai-status','ai-status-slot');el('ai-status').textContent='Preparando asistente…';
  const modelOptions=el('ai-options-slot').parentElement;
  el('ai-status-slot').after(el('ai-files-details'),modelOptions,el('ai-config-slot'));
  const sourceNotice=document.createElement('p');sourceNotice.className='ai-inline-hint';sourceNotice.textContent='El contenido de las fuentes se envía al proveedor configurado al analizar y generar. Revisa las citas y recomendaciones del borrador.';el('ai-options-slot').append(sourceNotice);
  // Reports remain available on demand; upload and generation live in the navigation.
  const preview=el('ai-source-preview');el('ai-sources').replaceChildren(preview);
  const draft=el('ai-draft');el('ai-generate').replaceChildren(draft);
  el('ai-title').textContent='Análisis y resultados';
  dialog.querySelector('[data-ai-tab="sources"]').textContent='Fuentes y citas';
  dialog.querySelector('[data-ai-tab="generate"]').textContent='Borradores';
  sidebar.addEventListener('keydown',event=>event.stopPropagation());
  sidebar.querySelectorAll('[data-report]').forEach(button=>button.onclick=()=>{if(!state)return;tab(button.dataset.report);render();dialog.showModal();});
  el('ai-login').onclick=()=>el('cloud-button').click();
  dialog.addEventListener('keydown',event=>event.stopPropagation());
  let state=null,projectId=null,activeTab='analysis',busy=false,config=null,languageCharts=[],loadVersion=0,ownerId=null,pendingFiles=[],pendingProject=null,cloudReload=false;
  const blank=()=>({version:1,sources:[],skipped:[],analysis:null,draft:null,context:[],prompt:'',provider:'',updatedAt:new Date().toISOString()});
  const db=new Promise((resolve,reject)=>{const request=indexedDB.open('domi-ai-workspaces',1);request.onupgradeneeded=()=>request.result.createObjectStore('workspaces');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(new Error('El navegador no permite guardar las fuentes.'));});
  async function store(key,value){const database=await db;return new Promise((resolve,reject)=>{const tx=database.transaction('workspaces',value===undefined?'readonly':'readwrite'),os=tx.objectStore('workspaces');const req=value===undefined?os.get(key):os.put(value,key);tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(new Error('No se pudieron guardar las fuentes. Exporta el expediente.'));});}
  function status(text,error=false){el('ai-status').textContent=text;el('ai-status').classList.toggle('error',error);}
  async function removeStored(key){const database=await db;return new Promise((resolve,reject)=>{const tx=database.transaction('workspaces','readwrite');tx.objectStore('workspaces').delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(new Error('No se pudo migrar el expediente local.'));});}
  const sync=window.DomiAISync.create({read:key=>store(key),write:(key,value)=>store(key,value),remove:removeStored,cloud:()=>window.DomiCloud,notify:(kind,error)=>{
    el('ai-sync-status').textContent=kind==='saved'?'Fuentes y borradores sincronizados en la nube.':kind==='syncing'?'Sincronizando fuentes…':kind==='error'?'Copia local conservada · sincronización pendiente. '+(error?.message||'Comprueba tu conexión.'):'Fuentes guardadas en este navegador.';
    el('ai-sync-status').classList.toggle('error',kind==='error');
  }});
  const apiClient=window.DomiAIClient.create({cloud:()=>window.DomiCloud,requiresLogin:()=>config?.requiresLogin!==false});
  const api=body=>apiClient.request(body);
  async function save(){state.updatedAt=new Date().toISOString();await sync.save(projectId,ownerId,state);}
  function tab(name){activeTab=name;dialog.querySelector('.ai-body').scrollTop=0;dialog.querySelectorAll('[data-ai-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.aiTab===name)));for(const key of ['sources','analysis','generate','dashboard','review'])el('ai-'+key).hidden=key!==name;if(name==='dashboard')requestAnimationFrame(renderDashboard);}
  dialog.querySelectorAll('[data-ai-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.aiTab));
  async function run(message,work){
    if(busy||!state)return;busy=true;status(message);sidebar.setAttribute('aria-busy','true');
    const controls=[...sidebar.querySelectorAll('button,input,textarea,select'),...dialog.querySelectorAll('button:not([data-ai-tab]):not(#ai-close)'),...['project-select','new-project','delete-project','new-map','load-example'].map(el)].filter(Boolean);
    const previous=controls.map(control=>control.disabled);controls.forEach(control=>control.disabled=true);
    try{await work();}catch(e){status(e.message||'No se pudo completar la operación.',true);if(e.status===401)el('ai-login').hidden=false;}
    finally{busy=false;sidebar.removeAttribute('aria-busy');controls.forEach((control,i)=>control.disabled=previous[i]);render();if(cloudReload||editor.projectId()!==projectId){cloudReload=false;await loadProject();}}
  }
  function evidence(refs){return (refs||[]).map(r=>`<div class="ai-evidence"><b>${escape(r.name)} · ${escape(r.locator)}</b><blockquote>${escape(r.quote)}</blockquote></div>`).join('');}
  function renderDashboard(){
    const host=el('ai-dashboard-content');if(!host||!state)return;languageCharts.forEach(chart=>chart.dispose());languageCharts=[];
    const detected=state.analysis?.languages||[],recommended=state.draft?.recommendedLanguages||[];
    host.innerHTML=`<div class="ai-dashboard-intro"><div><span class="eyebrow">TECNOLOGÍAS DEL PROYECTO</span><h3>Lenguajes detectados y recomendados</h3></div><p>Los detectados se calculan por extensión y volumen del código cargado. Las recomendaciones provienen del borrador y muestran prioridad relativa; no representan confianza estadística.</p></div><div class="ai-dashboard-grid"><div class="ai-card"><h3>Detectados en el código</h3>${detected.length?'<div id="ai-detected-chart" class="ai-chart" aria-label="Gráfico de lenguajes detectados"></div>'+detected.map(x=>`<div class="ai-language-row"><span>${escape(x.name)}</span><b>${x.percent.toFixed(1)}%</b><small>${x.files} archivo${x.files===1?'':'s'} · ${x.characters.toLocaleString('es')} caracteres</small></div>`).join(''):'<div class="ai-empty"><b>Sin lenguajes detectados</b><p>Conecta un repositorio público o carga un ZIP de código para obtener esta distribución.</p></div>'}</div><div class="ai-card"><h3>Recomendados para las instrucciones</h3>${recommended.length?'<div id="ai-recommended-chart" class="ai-chart" aria-label="Gráfico de lenguajes recomendados"></div>'+recommended.map((x,i)=>`<details class="ai-language-reason"><summary>${i+1}. ${escape(x.name)}</summary><p>${escape(x.reason)}</p>${evidence(x.evidence)||'<p class="ai-muted">Recomendación creativa sin fuente documental.</p>'}</details>`).join(''):'<div class="ai-empty"><b>Sin recomendaciones de lenguajes</b><p>Pide explícitamente lenguajes recomendados en el prompt para completar esta parte del dashboard.</p></div>'}</div></div>`;
    if(!window.echarts)return;
    if(detected.length){const chart=window.echarts.init(el('ai-detected-chart'));chart.setOption({animationDuration:450,tooltip:{trigger:'item',formatter:p=>`${escape(p.name)}<br>${Number(p.value).toLocaleString('es')} caracteres · ${p.percent.toFixed(1)}%`},legend:{type:'scroll',bottom:0},series:[{type:'pie',radius:['40%','67%'],center:['50%','43%'],avoidLabelOverlap:true,itemStyle:{borderColor:'#fff',borderWidth:3},label:{formatter:'{b}\n{d}%'},data:detected.map(x=>({name:x.name,value:x.characters}))}]});languageCharts.push(chart);}
    if(recommended.length){const chart=window.echarts.init(el('ai-recommended-chart'));const ordered=[...recommended].reverse();chart.setOption({animationDuration:450,grid:{left:85,right:25,top:15,bottom:30},tooltip:{trigger:'axis',axisPointer:{type:'shadow'},formatter:p=>{const item=recommended[recommended.length-1-p[0].dataIndex];return `<b>${escape(item.name)}</b><br>${escape(item.reason)}`;}},xAxis:{type:'value',show:false,max:recommended.length},yAxis:{type:'category',data:ordered.map(x=>x.name),axisTick:{show:false},axisLine:{show:false}},series:[{type:'bar',data:ordered.map((_,i)=>i+1),barMaxWidth:24,itemStyle:{color:'#267454',borderRadius:[0,5,5,0]},label:{show:true,position:'right',formatter:p=>`Prioridad ${recommended.length-p.dataIndex}`}}]});languageCharts.push(chart);}
  }
  function render(){if(!state)return;el('ai-project-name').textContent=editor.projectName();el('ai-source-count').textContent=state.sources.length;
    el('ai-source-list').innerHTML=state.sources.length?state.sources.map(s=>`<div class="ai-source"><strong>${escape(s.name)}</strong><small>${s.sections.reduce((n,p)=>n+p.text.length,0).toLocaleString('es')} caracteres · ${escape(s.type||'texto')}${s.origin?' · commit '+escape(s.origin.commit.slice(0,8)):''}</small><button type="button" data-ai-view="${escape(s.id)}">Ver texto y análisis</button><button type="button" data-ai-remove="${escape(s.id)}">Quitar de las fuentes</button></div>`).join(''):'<div class="ai-empty"><b>Tu contexto empieza aquí</b><p>Agrega documentos, código o una descripción para obtener un borrador con referencias.</p></div>';
    el('ai-source-list').querySelectorAll('[data-ai-view]').forEach(b=>b.onclick=()=>{const s=state.sources.find(x=>x.id===b.dataset.aiView);const preview=el('ai-source-preview');preview.hidden=false;tab('sources');dialog.showModal();preview.innerHTML=`<h3>${escape(s.name)}</h3>${s.warnings?.length?`<p class="ai-notice">${s.warnings.map(escape).join('<br>')}</p>`:''}${s.profile?`<details><summary>Perfil de datos: tipos, nulos y distribución</summary><pre>${escape(JSON.stringify(s.profile,null,2))}</pre></details>`:''}${s.symbols?`<details><summary>Estructura de código (AST)</summary><pre>${escape(JSON.stringify(s.symbols,null,2))}</pre></details>`:''}<pre>${escape(s.sections.map(p=>p.locator+'\n'+p.text).join('\n\n'))}</pre>`;});
    el('ai-source-list').querySelectorAll('[data-ai-remove]').forEach(b=>b.onclick=()=>run('Actualizando fuentes…',async()=>{state.sources=state.sources.filter(s=>s.id!==b.dataset.aiRemove);invalidate();await analyze();el('ai-source-preview').hidden=true;status('Fuente retirada; el borrador anterior se conserva en su expediente exportado, si lo descargaste.');}));
    el('ai-skipped').innerHTML=state.skipped.length?`<details><summary>${state.skipped.length} archivos omitidos · ver motivos</summary>${state.skipped.map(s=>`<p>${escape(s.name)}: ${escape(s.reason)}</p>`).join('')}</details>`:'';
    const a=state.analysis;el('ai-analysis-content').innerHTML=a?`<div class="ai-pipeline"><span>✓ Extracción</span><span>✓ Perfil / EDA</span><span>✓ Fragmentación</span><span class="${state.embedding?.configured?'':'pending'}">${state.embedding?.configured?'✓ Embeddings semánticos':'Embeddings semánticos pendientes'}</span><span>✓ Clustering ${state.embedding?.configured?'semántico':'léxico'}</span></div><div class="ai-stats">${[[a.sources,'fuentes'],[a.characters,'caracteres'],[a.chunks,'fragmentos'],[a.uniqueTerms,'términos únicos']].map(([v,l])=>`<div class="ai-stat"><strong>${Number(v).toLocaleString('es')}</strong><span>${l}</span></div>`).join('')}</div><div class="ai-grid"><div class="ai-card"><h3>Agrupaciones temáticas</h3><p class="ai-muted">K-means esférico determinista sobre ${state.embedding?.configured?'embeddings semánticos':'vectores TF-IDF'}. Estas agrupaciones no prueban relaciones de negocio.</p>${a.clusters.map(c=>`<div class="ai-cluster"><b>Grupo ${c.id+1}</b> · ${c.count} fragmentos<small>${c.terms.map(escape).join(' · ')}</small></div>`).join('')}</div><div class="ai-card"><h3>Informe de prospección</h3><p>Longitud de fragmentos: mínimo ${a.chunkLength.min}, máximo ${a.chunkLength.max}, media ${a.chunkLength.mean.toFixed(1)}.</p><p>Índice: ${escape(state.embedding?.provider||'TF-IDF')} / ${escape(state.embedding?.model||'léxico')}</p>${a.warnings.map(w=>`<p class="ai-notice">${escape(w)}</p>`).join('')||'<p class="ai-muted">Sin avisos de extracción.</p>'}<p class="ai-muted">Los perfiles de Excel y CSV muestran estadísticas por columna en “Ver texto y análisis”.</p></div></div>`:'<div class="ai-empty"><b>Aún no hay contenido para analizar</b><p>Carga tus primeras fuentes para calcular estadísticas y preparar el índice.</p></div>';
    const hasSources=state.sources.length>0;el('ai-mode').value=workflow.mode(state.sources);el('ai-inline-mode').textContent=hasSources?'Usará '+state.sources.length+(state.sources.length===1?' fuente':' fuentes')+' como contexto.':'Sin archivos: creará un borrador a partir de tu idea.';el('ai-mode').disabled=hasSources;el('ai-mode-note').textContent=hasSources?'Las fuentes cargadas obligan a usar el modo basado en evidencia.':'Sin fuentes: selecciona creación por prompt para proponer un esquema nuevo.';
    const selected=workflow.provider(config,state.provider),old=el('ai-model').value;if(selected){state.provider=selected.id;el('ai-provider').value=selected.id;}for(const option of el('ai-provider').options)option.disabled=!config?.providers?.find(p=>p.id===option.value)?.configured;el('ai-model-label').textContent=selected?.label||'';el('ai-model').innerHTML=selected?.models?.length?selected.models.map(m=>`<option value="${escape(m)}">${escape(m)}</option>`).join(''):'<option value="">Sin modelos configurados</option>';if(selected?.models?.includes(old))el('ai-model').value=old;
    const needsLogin=!!config?.requiresLogin&&document.body.dataset.cloud!=='online';
    el('ai-login').hidden=!needsLogin;
    el('ai-config-note').textContent=needsLogin?'Inicia sesión para usar tus fuentes y generar.':selected?.configured?(hasSources&&!config.embedding?.configured?'Falta configurar embeddings para usar documentos.':selected.label+' listo · el resultado será editable.'):'No hay modelos disponibles. Revisa la configuración de IA.';
    el('ai-generate-button').disabled=busy||!selected?.configured||(hasSources&&!config?.embedding?.configured);
    const d=state.draft;el('ai-draft').innerHTML=d?`<span class="ai-badge">BORRADOR · ${escape(d.provider)} / ${escape(d.model)}</span><h3 style="margin-top:14px">${escape(d.title)}</h3><p>${d.nodes.length} nodos · ${d.edges.length} relaciones · ${d.recommendations.length} recomendaciones</p><p class="ai-muted">${d.grounded?(d.citationIssues?.length?'Borrador generado; algunas citas requieren revisión.':'Citas localizadas en las fuentes. La validez semántica sigue pendiente de tu revisión.'):'Propuesta creativa sin evidencia documental.'} Las agrupaciones son propuestas visuales.</p>${d.citationIssues?.length?`<details class="ai-notice" open><summary>Informe de citas · ${d.citationIssues.length} observaciones</summary><p>El borrador continúa. Estas afirmaciones quedaron sin respaldo literal y requieren revisión:</p>${d.citationIssues.map(issue=>`<p><b>${escape(issue.where)}</b>: ${escape(issue.reason)}${issue.quote?`<br><code>${escape(issue.quote)}</code>`:''}</p>`).join('')}</details>`:''}${d.limitations?`<p class="ai-notice">${escape(d.limitations)}</p>`:''}<div class="ai-draft-list">${d.nodes.map(n=>`<details><summary>${escape(n.name)} ${n.group?'· '+escape(n.group):''}${n.unverified?' · sin evidencia':''}</summary>${evidence(n.evidence)}${n.fields.map(f=>`<p><b>${escape(f.name)}</b>: ${escape(f.type)}${f.unverified?' · sin evidencia':''}</p>${evidence(f.evidence)}`).join('')}</details>`).join('')}${d.edges.map(e=>`<details><summary>${escape(d.nodes.find(n=>n.id===e.from)?.name)} → ${escape(d.nodes.find(n=>n.id===e.to)?.name)} · ${escape(e.label)}${e.unverified?' · sin evidencia':''}</summary>${evidence(e.evidence)}</details>`).join('')}</div><div class="ai-actions"><button type="button" id="ai-import-draft" class="ai-primary">Abrir como proyecto editable</button><button type="button" id="ai-see-recs" class="ai-secondary">Revisar recomendaciones</button></div>`:'<div class="ai-empty"><b>Tu siguiente mapa empieza con una pregunta</b><p>Genera desde la barra izquierda. El esquema se abrirá en el lienzo y aquí podrás revisar sus citas.</p></div>';
    el('ai-rec-count').textContent=d?.recommendations.length||'';
    if(state.history?.length){const history=document.createElement('details');history.className='ai-cluster';history.innerHTML=`<summary>Historial · ${state.history.length} borradores anteriores</summary>${state.history.map((h,i)=>`<div class="ai-source"><strong>${escape(h.draft.title)}</strong><small>${escape(new Date(h.draft.createdAt).toLocaleString())}</small><button type="button" data-ai-history="${i}">Restaurar para revisar</button></div>`).join('')}`;el('ai-draft').append(history);history.querySelectorAll('[data-ai-history]').forEach(b=>b.onclick=()=>run('Abriendo revisión anterior…',async()=>{const [previous]=state.history.splice(Number(b.dataset.aiHistory),1);archiveDraft();state.draft=previous.draft;state.context=previous.context;await save();status('Borrador histórico recuperado. Sus citas corresponden a las fuentes de esa generación.');}));}
    el('ai-recommendations').innerHTML=d?.recommendations.length?`<p class="ai-muted">${d.recommendations.filter(r=>r.reviewed).length} revisadas · ${d.recommendations.filter(r=>r.accepted).length} aceptadas</p>`+d.recommendations.map(r=>`<div class="ai-review-item"><p>${escape(r.text)}</p><details><summary>Consultar evidencia</summary>${evidence(r.evidence)||'<p class="ai-muted">Propuesta creativa sin fuentes.</p>'}</details><label class="ai-check"><input type="checkbox" data-rec="${r.id}" data-decision="reviewed" ${r.reviewed?'checked':''}>Revisada</label><label class="ai-check"><input type="checkbox" data-rec="${r.id}" data-decision="accepted" ${r.accepted?'checked':''} ${!r.reviewed?'disabled':''}>Aceptada</label></div>`).join(''):'<div class="ai-empty"><b>No hay recomendaciones pendientes</b><p>Aquí aparecerán las propuestas del modelo después de generar un borrador.</p></div>';
    el('ai-recommendations').querySelectorAll('[data-rec]').forEach(input=>input.onchange=async()=>{try{const r=state.draft.recommendations.find(x=>x.id===input.dataset.rec);core.reviewRecommendation(r,input.dataset.decision,input.checked);await save();status('Decisión guardada.');render();}catch(e){status(e.message,true);}});
    if(activeTab==='dashboard')requestAnimationFrame(renderDashboard);
    if(el('ai-import-draft'))el('ai-import-draft').onclick=()=>run('Abriendo el borrador…',async()=>{await openDraft();dialog.close();status('Borrador abierto en el lienzo.');});
    if(el('ai-see-recs'))el('ai-see-recs').onclick=()=>tab('review');
  }
  function archiveDraft(){if(state.draft)state.history=[...(state.history||[]),{draft:state.draft,context:state.context}].slice(-10);}
  function invalidate(){archiveDraft();state.analysis=null;state.embedding=null;state.index=null;state.draft=null;state.context=[];}
  async function analyze(){const chunks=core.chunkSources(state.sources);if(chunks.length>250)throw new Error('Máximo 250 fragmentos; divide las fuentes.');state.index=null;state.analysis=core.summarize(state.sources,chunks);state.embedding={provider:'TF-IDF',model:'léxico',configured:false};await save();if(config?.embedding?.configured&&state.sources.length){status('Calculando embeddings y clustering semántico…');const result=await api({action:'analyze',sources:state.sources,semantic:true});state.analysis=result.analysis;state.embedding=result.embedding;state.index={chunks:result.chunks,vectors:result.vectors};await save();}}
  async function add(sources,skipped=[]){const next=[...state.sources];let duplicates=0;for(const s of sources){if(next.some(n=>n.id===s.id)){duplicates++;continue;}next.push(s);}if(next.length>80||next.reduce((n,s)=>n+s.sections.reduce((m,p)=>m+p.text.length,0),0)>300000||core.chunkSources(next).length>250)throw new Error('La carga supera 80 fuentes, 250 fragmentos o 300.000 caracteres. Divide el proyecto.');state.skipped=skipped.slice(-2000);if(next.length===state.sources.length){await save();status('No se agregaron fuentes nuevas. Consulta los duplicados o archivos omitidos.');return;}state.sources=next;invalidate();await analyze();status('Fuentes guardadas y analizadas.'+(duplicates?' Se omitieron '+duplicates+' duplicados.':'')+(!state.embedding?.configured?' Embeddings semánticos pendientes de configuración.':''));}
  async function loadProject(){
    if(busy)return;const version=++loadVersion,id=editor.projectId();sidebar.inert=true;
    try{const currentSession=await window.DomiCloud?.getSession();const nextOwner=currentSession?.user?.id||null;const loaded=(await sync.load(id,nextOwner))||blank();if(version!==loadVersion||id!==editor.projectId())return;
      if(ownerId&&ownerId!==nextOwner){pendingFiles=[];el('ai-retry-upload').hidden=true;}ownerId=nextOwner;
      projectId=id;state=loaded;el('ai-prompt').value=state.prompt||'';el('ai-provider').value=state.provider||'';
      el('ai-source-preview').hidden=true;render();status('Carga tus fuentes o escribe una idea para empezar.');
      if(!config)config=await api();if(version!==loadVersion)return;render();
    }catch(e){status(e.message,true);}finally{if(version===loadVersion)sidebar.inert=false;}
  }
  window.addEventListener('domi:projects-changed',()=>{if(!busy&&editor.projectId()!==projectId)loadProject();else if(state)el('ai-project-name').textContent=editor.projectName();});
  window.addEventListener('domi:cloud-state',()=>{if(busy){cloudReload=true;return;}loadProject();});
  window.addEventListener('online',()=>{if(busy){cloudReload=true;return;}loadProject();});
  loadProject();
  el('ai-close').onclick=()=>{languageCharts.forEach(chart=>chart.dispose());languageCharts=[];dialog.close();};
  window.addEventListener('resize',()=>languageCharts.forEach(chart=>chart.resize()));
  el('ai-upload').onclick=()=>el('ai-file').click();
  el('ai-retry-upload').onclick=()=>{if(editor.projectId()!==pendingProject)return status('Selecciona el proyecto donde comenzaste la carga para reintentar.',true);uploadFiles(pendingFiles);};
  async function uploadFiles(files){return run('Leyendo archivos…',async()=>{
    if(files.length>80)throw new Error('Selecciona como máximo 80 archivos.');
    pendingFiles=files;pendingProject=projectId;el('ai-retry-upload').hidden=!files.length;
    await apiClient.session();
    const result=await window.DomiAIClient.batch(files,async(f,i)=>{
      status(`Procesando ${i+1}/${files.length}: ${f.name}…`);
      const invalid=message=>Object.assign(new Error(message),{code:'FILE_INVALID'});
      if(!/\.(xls|xlsx|pdf|docx|txt|md|markdown|csv|tsv|json|zip|js|ts|tsx|jsx|mjs|cjs|py|sql|java|go|rs|php|rb|html|css|yaml|yml|xml|mmd|mermaid|png|jpg|jpeg|webp)$/i.test(f.name))throw invalid(/\.(mp4|mov|webm|avi)$/i.test(f.name)?'Carga la transcripción del video como TXT, DOCX o PDF.':'Formato no admitido. Usa Excel, PDF, DOCX, texto, código o imágenes.');
      if(f.size>2500000)throw invalid('Supera 2,5 MB.');
      const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(invalid('No se pudo leer el archivo.'));reader.readAsDataURL(f);});
      return api({action:'extract',name:f.name,data});
    });
    pendingFiles=result.pending;el('ai-retry-upload').hidden=!pendingFiles.length;
    if(result.sources.length||result.skipped.length)await add(result.sources,result.skipped);
    if(result.error)throw result.error;
    if(result.skipped.length)status(`Carga terminada: ${result.sources.length} fuentes procesadas, ${result.skipped.length} archivos omitidos. Consulta los motivos.`,!result.sources.length);
  });}
  el('ai-text-add').onclick=()=>run('Analizando texto…',async()=>{const text=el('ai-text').value.trim();if(!text)throw new Error('Pega un texto antes de agregarlo.');const name=(el('ai-text-name').value.trim()||'Texto pegado')+'.txt';const bytes=new TextEncoder().encode(name+'\n'+text),digest=await crypto.subtle.digest('SHA-256',bytes),id=Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join('');await add([{id,name,type:'texto',bytes:bytes.length,sections:[{locator:'texto pegado',text}],warnings:[]}]);el('ai-text').value='';el('ai-text-name').value='';});
  el('ai-file').onchange=event=>{const files=[...event.target.files];event.target.value='';uploadFiles(files);};
  el('ai-upload').ondragover=event=>{event.preventDefault();event.dataTransfer.dropEffect='copy';};
  el('ai-upload').ondrop=event=>{event.preventDefault();if(!busy)uploadFiles([...event.dataTransfer.files]);};
  el('ai-git-add').onclick=()=>run('Consultando la revisión del repositorio y extrayendo archivos…',async()=>{const result=await api({action:'git',url:el('ai-git').value.trim()});await add(result.sources,result.skipped);});
  el('ai-analyze').onclick=()=>run('Actualizando análisis…',async()=>{config=await api();await analyze();status(state.embedding.configured?'Índice semántico preparado.':'Análisis léxico listo. Falta configurar embeddings semánticos.');});
  el('ai-provider').onchange=()=>{state.provider=el('ai-provider').value;save().catch(e=>status(e.message,true));render();};
  el('ai-prompt').onchange=()=>{state.prompt=el('ai-prompt').value;save().catch(e=>status(e.message,true));};
  async function openDraft(){
    const map=core.toMap(state.draft);window.SchemaModel.validate(map);await save();
    const next=editor.importDraft(map);await sync.save(next,ownerId,state);projectId=next;
  }
  el('ai-generate-button').onclick=()=>run('Generando esquema… puede tardar hasta un minuto.',async()=>{
    if(config?.requiresLogin&&!(await window.DomiCloud?.getSession())){el('ai-login').hidden=false;throw new Error('Inicia sesión para generar. Tu prompt y tus fuentes se conservan.');}
    const request=workflow.request(state,config,el('ai-prompt').value,el('ai-model').value);
    state.prompt=request.prompt;state.provider=request.provider;await save();
    const result=await api(request);archiveDraft();state.draft=result.draft;state.context=result.context;
    if(result.analysis)state.analysis=result.analysis;if(result.embedding)state.embedding=result.embedding;await save();
    await openDraft();render();status('Esquema creado en un proyecto nuevo. Ya puedes editarlo en el lienzo.');
  });
  el('ai-export').onclick=()=>{if(!state)return;const blob=new Blob([JSON.stringify({project:editor.projectName(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='domi-expediente-ia.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  el('ai-save-cloud').onclick=()=>run('Guardando fuentes y revisión en Supabase…',async()=>{if(!window.DomiCloud)throw new Error('La conexión de nube no está disponible.');await window.DomiCloud.saveAI(projectId,state,ownerId);status('Fuentes, análisis y revisión guardados en Supabase.');});
  el('ai-load-cloud').onclick=()=>run('Buscando expediente en Supabase…',async()=>{if(!window.DomiCloud)throw new Error('La conexión de nube no está disponible.');const cloud=await window.DomiCloud.loadAI(projectId);if(!cloud)throw new Error('Este proyecto no tiene un expediente en la nube.');if(!Array.isArray(cloud.sources)||cloud.version!==1)throw new Error('Expediente no compatible.');if(state.sources.length&&new Date(state.updatedAt)>new Date(cloud.updatedAt))throw new Error('Tu expediente local es más reciente. Guárdalo en nube antes de reemplazarlo.');state=cloud;await sync.save(projectId,ownerId,state);el('ai-prompt').value=state.prompt||'';el('ai-provider').value=state.provider||'openai';status('Expediente recuperado.');});
})();
